def _clave():
    ruta = os.path.join(CACHE, "clave")
    try:
        c = open(ruta).read().strip()
        if re.fullmatch(r"[0-9a-f]{32}", c):
            return c
    except OSError:
        pass
    c = secrets.token_hex(16)
    fd = os.open(ruta, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as f:
        f.write(c)
    return c


