def _epoch(t):
    try:
        if isinstance(t, (int, float)):
            return float(t)
        return calendar.timegm(time.strptime(t[:19], "%Y-%m-%dT%H:%M:%S")) - _desfase(t)
    except Exception:
        return None


def _desfase(t):
    m = re.search(r"([+-])(\d\d):?(\d\d)$", t[19:])
    if m:
        return (1 if m.group(1) == "+" else -1) * (int(m.group(2)) * 3600 + int(m.group(3)) * 60)
    return -time.timezone if not time.localtime().tm_isdst else -time.altzone














