def _lineas_cola(ruta, cuanto=65536):
    try:
        with open(ruta, "rb") as f:
            f.seek(0, 2)
            f.seek(max(0, f.tell() - cuanto))
            return f.read().split(b"\n")[1:]
    except OSError:
        return []


_uso = {}
_uso_modelo = {}


def uso(ruta):
    m = os.path.getmtime(ruta)
    if ruta in _uso and _uso[ruta][0] == m and time.time() - _uso[ruta][3] < 60:
        return _uso[ruta][1:3]
    ctx, hora, ahora = None, 0, time.time()
    for ln in _lineas_cola(ruta, 2_000_000):
        if b'"usage"' not in ln:
            continue
        try:
            d = json.loads(ln)
        except ValueError:
            continue
        u = (d.get("message") or {}).get("usage") if d.get("type") == "assistant" else None
        if not u:
            continue
        ctx = sum(u.get(x, 0) for x in ("input_tokens", "cache_read_input_tokens", "cache_creation_input_tokens", "output_tokens"))
        _uso_modelo[ruta] = (d.get("message") or {}).get("model") or _uso_modelo.get(ruta)
        try:
            t = calendar.timegm(time.strptime(d["timestamp"][:19], "%Y-%m-%dT%H:%M:%S"))
        except (KeyError, ValueError):
            continue
        if ahora - t < 3600:
            hora += sum(u.get(x, 0) for x in ("input_tokens", "cache_creation_input_tokens", "output_tokens"))
    _uso[ruta] = (m, ctx, hora, ahora)
    return ctx, hora


def _cola(ruta):
    for ln in reversed(_lineas_cola(ruta)):
        try:
            d = json.loads(ln)
        except ValueError:
            continue
        c = (d.get("message") or {}).get("content")
        if d.get("type") == "assistant" and isinstance(c, list):
            for x in reversed(c):
                if x.get("type") == "tool_use":
                    return x.get("name"), _corto(x.get("name"), x.get("input"))
    return None, ""


