def _lee_ganchos():
    try:
        tam = os.path.getsize(EVENTOS)
    except OSError:
        return _ganchos["ultimo"]
    if tam > 20_000_000:
        os.replace(EVENTOS, EVENTOS + ".1")
        _ganchos["pos"] = 0
        return _ganchos["ultimo"]
    if tam < _ganchos["pos"]:
        _ganchos["pos"] = 0
    with open(EVENTOS, "rb") as f:
        f.seek(_ganchos["pos"])
        trozo = f.read()
    corte = trozo.rfind(b"\n")
    if corte < 0:
        return _ganchos["ultimo"]
    _ganchos["pos"] += corte + 1
    ahora = time.time()
    for ln in trozo[:corte].decode("utf-8", "replace").split("\n"):
        sid = re.search(r'"session_id":"([0-9a-f-]+)"', ln)
        ev = re.search(r'"hook_event_name":"(\w+)"', ln)
        if not sid or not ev:
            continue
        herr = re.search(r'"tool_name":"([^"]+)"', ln)
        que = re.search(r'"(?:description|file_path|to|notification_type)":"([^"]{0,80})', ln)
        _ganchos["ultimo"][sid.group(1)] = (ahora, ev.group(1), herr.group(1) if herr else None,
                                           que.group(1) if que else "")
    return _ganchos["ultimo"]


def _subagentes_vivos(ruta):
    if not ruta:
        return []
    out, ahora = [], time.time()
    for f in glob.glob(ruta[:-6] + "/subagents/*.jsonl"):
        if ahora - os.path.getmtime(f) > 90:
            continue
        try:
            cab = open(f, "rb").read(6000).decode("utf-8", "replace")
        except OSError:
            continue
        m = re.search(r'"description":"([^"]{1,60})', cab)
        out.append(m.group(1) if m else "subagente")
    return out
















































































