def reconcilia(p, sesiones):
    por_sid = {x["sessionId"]: x.get("name") for x in sesiones}
    por_nombre = {x.get("name"): x["sessionId"] for x in sesiones}
    cambio = False
    for sala, nombre in list(p["directivos"].items()):
        sid = p["sids"].get(sala)
        if sid in por_sid and por_sid[sid] and por_sid[sid] != nombre:
            p["directivos"][sala] = por_sid[sid]
            cambio = True
        elif nombre in por_nombre and sid not in por_sid:
            p["sids"][sala] = por_nombre[nombre]
            cambio = True
    for sala in [k for k in p["sids"] if k not in p["directivos"]]:
        del p["sids"][sala]
        cambio = True
    if cambio:
        guarda_plano(p)
    return p


