def mueve_rotulo(de, a):
    de, a = str(de), str(a)
    if de == a:
        return "ok"
    r, p = _lee_json(ROTULOS, {}), plano()
    r[de], r[a] = r.get(a), r.get(de)
    r = {k: v for k, v in r.items() if v}
    if a in p["directivos"]:
        p["directivos"][de] = p["directivos"].pop(a)
        if a in p["sids"]:
            p["sids"][de] = p["sids"].pop(a)
        guarda_plano(p)
    _escribe_json(ROTULOS, r, ensure_ascii=False)
    return "ok"


