def guarda_plano(p):
    os.makedirs(CACHE, exist_ok=True)
    antes = _lee_json(PLANO, {"directivos": {}, "sids": {}})
    cambios = {k: [antes.get("directivos", {}).get(k), p["directivos"].get(k)]
               for k in set(antes.get("directivos", {})) | set(p["directivos"])
               if antes.get("directivos", {}).get(k) != p["directivos"].get(k)}
    if cambios:
        with open(os.path.join(CACHE, "plano.log"), "a") as f:
            f.write(json.dumps({"t": time.strftime("%H:%M:%S"), "por": sys._getframe(1).f_code.co_name, "cambios": cambios}, ensure_ascii=False) + "\n")
    _escribe_json(PLANO, p, ensure_ascii=False, indent=1)




