_tmp_n = itertools.count()


def _escribe_texto(ruta, txt):
    tmp = f"{ruta}.nuevo.{os.getpid()}.{threading.get_ident()}.{next(_tmp_n)}"
    try:
        with open(tmp, "w") as fh:
            fh.write(txt)
        os.replace(tmp, ruta)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _escribe_json(ruta, obj, **kw):
    _escribe_texto(ruta, json.dumps(obj, **kw))


