def _cacheado(ruta, lee):
    try:
        st = os.stat(ruta)
    except OSError:
        return None
    c = _porfich.get(ruta)
    if not c or c[:2] != (st.st_mtime, st.st_size):
        try:
            r = lee(ruta)
        except (OSError, ValueError, TypeError, KeyError, AttributeError):
            r = None
        c = _porfich[ruta] = (st.st_mtime, st.st_size, r)
    return c[2]


def _lee_enviados(ruta):
    out, vistos = {}, set()
    for ln in open(ruta):
        try:
            e = json.loads(ln)
        except ValueError:
            continue
        if e.get("id") in vistos:
            continue
        vistos.add(e.get("id"))
        if _de_user(e) and e.get("sid") and e.get("t", 0) > out.get(e["sid"], (0,))[0]:
            out[e["sid"]] = (e["t"], e.get("texto", ""))
    return out


