def _lee_notas(ruta):
    mt, mejor = os.path.getmtime(ruta), None
    for x in json.load(open(ruta)):
        if not isinstance(x, dict) or x.get("quien", USER_AULA) != USER_AULA:
            continue
        t = x.get("creada")
        if not isinstance(t, (int, float)):
            try:
                t = time.mktime(time.strptime(str(x.get("fecha", ""))[:16], "%Y-%m-%d %H:%M"))
            except ValueError:
                t = mt
        if not mejor or t > mejor[0]:
            mejor = (t, " ".join(str(x.get("texto") or "").split()))
    return mejor


def _titulo(ruta):
    pat = re.compile(rb'"customTitle":"[^"]*"')
    r = []
    try:
        with open(ruta, "rb") as f:
            tam = f.seek(0, 2)
            for desde in (max(0, tam - 2_000_000), 0):
                f.seek(desde)
                r = [x.decode() for x in pat.findall(f.read())]
                if r or desde == 0:
                    break
    except OSError:
        r = []
    return json.loads("{" + r[-1] + "}")["customTitle"] if r else None


