def _salas_estado(agentes, pl, sesiones):
    loc = salas_estado_local()
    sala_de = {v: int(k) for k, v in pl["directivos"].items()}
    for a in agentes:
        k = llave(a["nombre"])
        o = dict(loc[k]) if k in loc else {"estado": "busy" if a["estado"] in ("busy", "shell") else "idle", "crudo": a["estado"], "caidas": 0, "ultima_caida": None,
                                           "supervisada": None, "retenida_swap": False, "detalle": None, "antiguedad": None, "fuente": "tmux", "sid": a["sid"]}
        conf = _conf_sala(a["nombre"])
        ruta = _ruta(a["sid"])
        o["ctx"] = a.get("ctx") if a.get("ctx") is not None else o.get("ctx")
        o["modelo"] = conf.get("modelo") or _uso_modelo.get(ruta) or o.get("modelo")
        try:
            o["sala"] = int(conf["sala"]) if conf.get("sala") else sala_de.get(a["nombre"], o.get("sala"))
        except ValueError:
            o["sala"] = sala_de.get(a["nombre"], o.get("sala"))
        a["sala_estado"] = o
        if k in loc:
            loc[k] = o
    for k, o in loc.items():
        if o.get("sala") is None:
            nom = next((n for n in pl["directivos"].values() if llave(n) == k), None)
            if nom is not None:
                o["sala"] = sala_de.get(nom)
    return loc


def _sesion(sid):
    return next((x for x in _sesiones() if x.get("sessionId") == sid), None)


def _textos(d):
    c = (d.get("message") or {}).get("content")
    a = d.get("attachment") or {}
    if d.get("type") == "assistant" and isinstance(c, list):
        t = " ".join(x.get("text", "") for x in c if x.get("type") == "text").strip()
        return ("agente", t) if t else None
    if d.get("type") == "attachment" and a.get("type") == "queued_command":
        t, origen = a.get("prompt"), a.get("origin") or {}
        humano = a.get("commandMode") == "prompt" and not a.get("isMeta")
    elif d.get("type") == "user" and isinstance(c, str):
        t, origen = c, d.get("origin") or {}
        humano = (d.get("turnOrigin") == "human" and d.get("promptSource") in ("typed", "queued", "suggestion_accepted")
                  and not (d.get("isMeta") or d.get("isCompactSummary") or d.get("isVisibleInTranscriptOnly")))
    else:
        return None
    if not isinstance(t, str):
        return None
    t = _sin_pegado(t)
    if origen.get("kind") == "peer":
        de = re.search(r'<cross-session-message[^>]*from-name="([^"]+)"', t)
        cuerpo = re.search(r'<cross-session-message[^>]*>\s*(.*?)\s*</cross-session-message>', t, re.S)
        return (de.group(1), cuerpo.group(1) if cuerpo else t) if de else None
    if AVISO_AUTO.match(t):
        return None
    if origen.get("kind") != "human" or not humano or re.fullmatch(r"/\S+", t.strip()):
        return None
    return (autor(t), t)


OCULTOS = []


def visible(t):
    for patron, por in OCULTOS:
        t = patron.sub(por, t)
    return t


def charla(sid, n=40, cola=1_500_000):
    s = _sesion(sid) or ({"name": "agente"} if cola > 1_500_000 and _ruta(sid) else None)
    if not s:
        return []
    out = []
    con_audio = [(_norm(e["texto"]), e["audio"]) for e in list(_envios) if e.get("sid") == sid and e.get("audio")]
    for ln in _lineas_cola(_ruta(sid) or "", cola):
        try:
            d = json.loads(ln)
            m = _textos(d)
        except ValueError:
            continue
        if m:
            out.append({"quien": s.get("name") if m[0] == "agente" else m[0], "texto": m[1][:20000], "uuid": d.get("uuid"),
                        **({"auto": True} if del_edificio(m[0]) else {}),
                        **({"audio": a} if m[0] == "Tú" and (a := next((_audios_ok(au) for t, au in con_audio if t and t in _norm(m[1])), None)) else {}),
                        **({"par": True} if ((d.get("attachment") or {}).get("origin") or d.get("origin") or {}).get("kind") == "peer" else {})})
    return out[-n:]


_ult_cache = {}


def _por_fichero(ruta, lee):
    try:
        st = os.stat(ruta)
    except OSError:
        return None
    c = _ult_cache.get(ruta)
    if not c or c[:2] != (st.st_mtime, st.st_size):
        try:
            r = lee(ruta)
        except (OSError, ValueError, TypeError, KeyError, AttributeError):
            r = None
        c = _ult_cache[ruta] = (st.st_mtime, st.st_size, r)
    return c[2]


def _de_user(e):
    t = e.get("texto", "")
    return (e.get("autor") or "user") == "user" and not e.get("que") and not re.fullmatch(r"/\S+", t.strip()) and es_de_user((autor(t), t))


def _lee_todos_envios(ruta):
    ult = {}
    for ln in open(ruta):
        try:
            e = json.loads(ln)
            ult[e["id"]] = e
        except (ValueError, KeyError):
            continue
    return sorted(ult.values(), key=lambda e: e.get("t", 0))


def _user_en_ruta(ruta):
    mejor, resp = None, False
    for ln in _lineas_cola(ruta, 600_000):
        try:
            d = json.loads(ln)
            m = _textos(d)
        except ValueError:
            continue
        if not m:
            continue
        if es_de_user(m):
            try:
                t = calendar.timegm(time.strptime(d.get("timestamp", "")[:19], "%Y-%m-%dT%H:%M:%S"))
            except ValueError:
                t = os.path.getmtime(ruta)
            mejor, resp = (t, m[1]), False
        elif mejor and m[0] == "agente":
            resp = True
    return (*mejor, resp) if mejor else None


def ultima_user(nombre):
    k = quien(nombre)
    if not k:
        return None
    _nombres_sids()
    todos = _por_fichero(ENVIADOS, _lee_todos_envios) or []
    suyos = [e for e in todos if e.get("sid") and _quien_sid(e["sid"]) == k]
    sids = {e["sid"] for e in suyos} | {s for s, q in list(_sid_quien.items()) if q == k}
    mias = [e for e in suyos if _de_user(e)]
    u = None
    if mias:
        e = mias[-1]
        u = {"texto": e["texto"], "t": e["t"], "estado": e["estado"], "motivo": e.get("motivo"), **({"audio": _audios_ok(e["audio"])} if e.get("audio") else {})}
    rutas = sorted((r for r in (_ruta(s) for s in sids) if r), key=lambda r: os.path.getmtime(r))[-4:]
    for r in rutas:
        x = _por_fichero(r, _user_en_ruta)
        if not x:
            continue
        if u and _norm(x[1]) == _norm(u["texto"]):
            if x[2] and u["estado"] != "contestado":
                u["estado"] = "contestado"
        elif not u or x[0] > u["t"] + 120:
            u = {"texto": x[1], "t": x[0], "estado": "contestado" if x[2] else "visto", "motivo": None}
    if not u:
        return None
    rel = next((e["t"] for e in suyos if e.get("que") == "relevo" and e["t"] > u["t"]), None)
    if rel and u["estado"] not in ("visto", "contestado"):
        u["estado"] = "visto"
    u["relevo"] = rel
    return u


CHINCHETAS = os.path.join(CACHE, "chinchetas.json")


_resp_chinch = {}


def _respuesta_clavada(sids, q):
    for sd in sids:
        ruta = _ruta(sd) if sd else None
        if not ruta:
            continue
        try:
            k = (sd, os.path.getmtime(ruta), q)
        except OSError:
            continue
        if k not in _resp_chinch:
            if len(_resp_chinch) > 200:
                _resp_chinch.clear()
            r = None
            if True:
                todo = charla(sd, 10_000, 30_000_000)
                i = next((j for j, m in enumerate(todo) if m["quien"] == "Tú" and m["texto"] == q), None)
                if i is not None:
                    rs = []
                    for m in todo[i + 1:]:
                        if m["quien"] == "Tú":
                            break
                        if not m.get("par"):
                            rs.append(m["texto"])
                    r = "\n\n".join(rs)
            _resp_chinch[k] = r
        if _resp_chinch[k] is not None:
            return _resp_chinch[k]
    return None


def chinchetas(sid):
    s = _sesion(sid)
    lista = _lee_json(CHINCHETAS, {}).get(quien(s.get("name")), []) if s else []
    out = []
    for c in lista:
        if c.get("solo_q") and c.get("q"):
            r = _respuesta_clavada([c.get("sid"), sid], c["q"])
            if r:
                c = {**c, "resp": r}
        out.append(c)
    return out


def chincheta(sid, uuid, texto, q):
    s = _sesion(sid)
    solo_q = not uuid and not texto and bool((q or "").strip())
    if not s or not (uuid or texto or solo_q):
        return "no"
    k, c = quien(s.get("name")), _lee_json(CHINCHETAS, {})
    lista = c.get(k, [])
    igual = [x for x in lista if (uuid and x.get("uuid") == uuid) or (not uuid and texto and x["r"] == texto)
             or (solo_q and x.get("solo_q") and x["q"] == q[:20000])]
    if igual:
        c[k] = [x for x in lista if x not in igual]
    else:
        todo = charla(sid, 10_000)
        i = next((j for j, m in enumerate(todo) if uuid and m["uuid"] == uuid), None)
        if i is not None:
            texto = todo[i]["texto"]
            q = next((m["texto"] for m in reversed(todo[:i]) if m["quien"] == "Tú"), q)
        lista.append({"id": secrets.token_hex(4), "nombre": s.get("name"), "sid": sid, "uuid": uuid,
                      "q": (q or "")[:20000], "r": (texto or "")[:20000], "t": time.time(), **({"solo_q": True} if solo_q else {})})
        c[k] = lista
    _escribe_json(CHINCHETAS, {a: b for a, b in c.items() if b}, ensure_ascii=False)
    marca_user(sid, "quitó una chincheta" if igual else "puso una chincheta", k)
    return "quitada" if igual else "puesta"


