def _huella(texto):
    return hashlib.sha1(_norm(texto).encode()).hexdigest()[:20]


def _registra(texto, autor_, que, guarda=True, h=None):
    _autoria.setdefault(h or _huella(texto), {})[autor_] = que
    if guarda:
        with open(TECLEADOS, "a") as f:
            f.write(json.dumps({"t": time.time(), "autor": autor_, "que": que, "h": h or _huella(texto), "texto": texto[:200]}, ensure_ascii=False) + "\n")


AVISO_AUTO = re.compile(r"^\s*\[(?:hook\b|prueba hook\b|Request interrupted|Cross-session|[^\]\n]{0,80}· revisión\b|(?!director\b|user\b|edificio\b)[A-Za-z][\w-]{1,40} · [^\]\n]{0,200}\])")


def _plantilla(texto):
    t = _norm(texto)
    return next((q for p, q in PLANTILLAS if p.search(t)), None)


def autor(texto):
    if AVISO_AUTO.match(texto or ""):
        return f"{EDIF} · aviso"
    reg = _autoria.get(_huella(texto))
    if reg:
        return "Tú" if set(reg) == {"user"} else f"{EDIF} · {reg.get('edificio') or 'aviso'}"
    q = _plantilla(texto)
    return f"{EDIF} · {q}" if q else "Tú"


AUTOMATICO = re.compile(r"\s*\[(?!Image\b)[^\]\n]{1,80}\]")


def es_de_user(m):
    return bool(m) and m[0] == "Tú" and not AUTOMATICO.match(m[1] or "")


def del_edificio(quien_):
    return (quien_ or "").startswith(EDIF + " · ")


