def _vigia_cambios():
    vistos, firma_estado, rutas, t_ses, t_estado, sucio = {}, None, {}, 0, 0, False
    while True:
        try:
            ahora = time.time()
            if ahora - t_ses > 2:
                t_ses = ahora
                rutas = {s["sessionId"]: _ruta(s["sessionId"]) for s in _sesiones() if s.get("sessionId")}
                f = (tuple(sorted(rutas)), _mtime(EVENTOS), _mtime(PLANO), _mtime(ROTULOS), _mtime(EMBLEMAS), _mtime(WEBS), version(), accion_user() and _acc["firma"], None)
                if f != firma_estado:
                    sucio, firma_estado = firma_estado is not None or sucio, f
            en_vuelo = {e["sid"] for e in list(_envios) if e["estado"] == "tecleado"}
            for sid, ruta in rutas.items():
                if not ruta:
                    continue
                try:
                    st = os.stat(ruta)
                except OSError:
                    continue
                k = (st.st_size, st.st_mtime)
                if vistos.get(sid) != k:
                    if sid in vistos:
                        emite("charla", sid)
                        sucio = True
                        if sid in en_vuelo:
                            _despierta.set()
                    vistos[sid] = k
            for sid_p, dir_p in PASARELAS.items():
                m_p = (_mtime(os.path.join(dir_p, "charla.json")), _mtime(os.path.join(dir_p, "envios.json")))
                if vistos.get(sid_p) != m_p:
                    if sid_p in vistos:
                        emite("charla", sid_p)
                    vistos[sid_p] = m_p
            if sucio and ahora - t_estado >= 1.5:
                emite("estado")
                sucio, t_estado = False, ahora
        except Exception as ex:
            print("vigía:", repr(ex), file=sys.stderr, flush=True)
        time.sleep(0.25)


def _mtime(ruta):
    try:
        return os.path.getmtime(ruta)
    except OSError:
        return None










def secrets_hash(x):
    import hashlib
    return hashlib.md5(x.encode()).hexdigest()[:12]
















def _comprueba(e):
    ruta = _ruta(e["sid"])
    if not ruta or "pos" not in e:
        return
    with open(ruta, "rb") as f:
        f.seek(e["pos"])
        trozo = f.read()
    corte = trozo.rfind(b"\n")
    if corte < 0:
        return
    e["pos"] += corte + 1
    buscado = _norm(e["texto"])
    for ln in trozo[:corte].decode("utf-8", "replace").split("\n"):
        try:
            d = json.loads(ln)
        except ValueError:
            continue
        cont = d.get("content") if d.get("type") == "queue-operation" else None
        m = _textos(d)
        llega = _norm(_sin_pegado(cont)) if isinstance(cont, str) else (_norm(m[1]) if m and m[0] != "agente" else "")
        if e["estado"] in ("tecleado", "no llegó entero", "no llegó") and llega:
            if buscado in llega:
                if e["estado"] != "tecleado":
                    e["motivo"] = "llegó tarde"
                e["estado"], e["visto"], e["desde"] = "visto", time.time(), time.time()
                _guarda_envio(e)
            elif (e["estado"] == "tecleado" and m and (es_de_user(m) or del_edificio(m[0])) and len(llega) >= 2
                  and (buscado.endswith(llega) or buscado.startswith(llega))):
                _cierra(e, "no llegó entero", f"llegó partido: solo «{llega[:80]}»; no se reintenta solo para no duplicarlo")
        elif e["estado"] == "visto" and m and m[0] == "agente":
            e["estado"], e["contestado"] = "contestado", time.time()
            _guarda_envio(e)
            return


def _sin_pegado(t):
    return re.sub(r'\s*<pasted_content id="\w+">\n?(.*?)\n?</pasted_content id="\w+">\s*', r"\1", t, flags=re.S).strip()






ATASCO = 30
CONFIRMA = 12
SIN_VER = 45


def _atascado(e):
    return (e["estado"] in ("pendiente", "retenido") and time.time() - e["t"] >= ATASCO) or \
           (e["estado"] in ("no llegó", "no llegó entero") and time.time() - e["t"] < 3600)


def retenidos():
    r = {}
    for e in list(_envios):
        if _atascado(e):
            r.setdefault(e["sid"], []).append({"id": e["id"], "texto": e["texto"][:200], "estado": e["estado"],
                                               "motivo": e.get("motivo"), "desde": e.get("desde", e["t"])})
    return r


def _cierra(e, estado, motivo=None):
    e["estado"], e["desde"] = estado, time.time()
    if motivo:
        e["motivo"] = motivo
    _guarda_envio(e)


def _motivo(e, estado, motivo):
    if e["estado"] != estado or e.get("motivo") != motivo:
        e["estado"], e["motivo"], e["desde"] = estado, motivo, time.time()
        _guarda_envio(e)


def _ordenes(e):
    o = e.pop("orden", None)
    if o == "cancelar" and e["estado"] in ("pendiente", "retenido", "no llegó", "no llegó entero"):
        _cierra(e, "cancelado", "cancelado por Tú")
    elif o == "reintentar" and e["estado"] in ("retenido", "no llegó", "no llegó entero"):
        for k in ("tecleado", "enter_extra", "pos", "visto"):
            e.pop(k, None)
        _cierra(e, "pendiente", "reintento pedido por Tú")




def _cartero():
    while True:
        try:
            with _cerrojo:
                lista = list(_envios)
            vivos = {x["sessionId"]: x for x in _sesiones()}
            colas = {}
            for e in lista:
                _ordenes(e)
                if e["estado"] in ("no llegó", "no llegó entero") and "pos" in e and time.time() - e["t"] < 600:
                    _comprueba(e)
                if e["estado"] in ("pendiente", "retenido", "tecleado", "visto"):
                    colas.setdefault(e["sid"], []).append(e)
            for sid, cola in colas.items():
                s = vivos.get(sid)
                for e in cola:
                    if e["estado"] in ("tecleado", "visto"):
                        _comprueba(e)
                    if e["estado"] == "tecleado" and e.get("via") == "tmux":
                        dt = time.time() - e["tecleado"]
                        if dt > CONFIRMA and not e.get("enter_extra"):
                            c = _caja(e["destino"])
                            if c and (c.startswith("[Pasted text") or _norm(c)[:40] == _norm(e["texto"])[:40]):
                                _tmux("send-keys", "-t", e["destino"], "Enter")
                                e["enter_extra"] = 1
                                _guarda_envio(e)
                        if dt > SIN_VER:
                            _cierra(e, "no llegó entero", "se tecleó a las " + time.strftime("%H:%M:%S", time.localtime(e["tecleado"]))
                                    + " y no aparece entero en su conversación; no se reintenta solo para no duplicarlo")
                    if e["estado"] == "tecleado":
                        break
                    if e["estado"] in ("pendiente", "retenido"):
                        _entrega(e, s, cola)
                        if e["estado"] in ("retenido", "tecleado"):
                            break
                for x in cola:
                    if x["estado"] == "pendiente" and time.time() - x["t"] >= ATASCO and x is not e:
                        _motivo(x, "pendiente", "en cola detrás de otro mensaje a la misma sesión: «" + _norm(e["texto"])[:50] + "»")
        except Exception as ex:
            print("cartero:", repr(ex), file=sys.stderr, flush=True)
        _despierta.wait(1)
        _despierta.clear()


