def _grabacion(ide):
    if not re.fullmatch(r"[0-9a-f]{16}", ide or ""):
        return None
    return next(iter(glob.glob(os.path.join(GRABACIONES, ide + ".*"))), None)


def _audios_ok(ids):
    return [i for i in ids if _grabacion(i)]


WHISPER = os.environ.get("PERCEBE_WHISPER") or shutil.which("whisper") or "/opt/homebrew/bin/whisper"
WHISPER_MODELO = os.environ.get("PERCEBE_WHISPER_MODELO", "small")
FFMPEG = os.environ.get("PERCEBE_FFMPEG") or shutil.which("ffmpeg") or "/opt/homebrew/bin/ffmpeg"
_trans = {}
_trans_q = queue.Queue()
_trans_hilo = None


def _transcribe_uno(ide):
    ruta = _grabacion(ide)
    if not ruta:
        raise OSError("la grabación no existe")
    if not os.path.exists(FFMPEG) or not os.path.exists(WHISPER):
        raise OSError("falta ffmpeg o whisper en este equipo")
    tmp = os.path.join(CACHE, "transcribe_tmp", ide)
    os.makedirs(tmp, exist_ok=True)
    try:
        wav = os.path.join(tmp, "a.wav")
        r = subprocess.run(["nice", "-n", "15", FFMPEG, "-y", "-loglevel", "error", "-i", ruta, "-ac", "1", "-ar", "16000", wav], capture_output=True, text=True, timeout=120)
        if r.returncode or not os.path.exists(wav):
            raise OSError("ffmpeg no pudo leer el audio: " + (r.stderr or "")[-200:])
        r = subprocess.run(["nice", "-n", "15", WHISPER, wav, "--model", WHISPER_MODELO, "--language", "es", "--fp16", "False", "--output_format", "txt", "--output_dir", tmp, "--verbose", "False"],
                           capture_output=True, text=True, timeout=900)
        txt = os.path.join(tmp, "a.txt")
        if r.returncode or not os.path.exists(txt):
            raise OSError("whisper falló: " + (r.stderr or "")[-300:])
        return re.sub(r"\s+", " ", open(txt, encoding="utf-8").read()).strip()
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def _trans_bucle():
    while True:
        job, ide = _trans_q.get()
        _trans[job]["estado"] = "transcribiendo"
        try:
            _trans[job].update(texto=_transcribe_uno(ide), estado="listo")
        except Exception as e:
            _trans[job].update(estado="error", error=str(e)[:300])
        for k in [k for k, v in _trans.items() if v["estado"] in ("listo", "error") and time.time() - v["t"] > 3600]:
            _trans.pop(k, None)


def transcribe_pide(ide):
    global _trans_hilo
    if not _grabacion(ide):
        return None
    with _cerrojo:
        if _trans_hilo is None:
            _trans_hilo = threading.Thread(target=_trans_bucle, daemon=True)
            _trans_hilo.start()
    job = secrets.token_hex(8)
    _trans[job] = {"estado": "cola", "texto": "", "t": time.time(), "delante": _trans_q.qsize()}
    _trans_q.put((job, ide))
    return job


def habla(sid, texto, autor_="edificio", que="aviso", audio=None):
    texto = (texto or "").strip()
    if not texto or not sid:
        return None
    e = {"id": secrets.token_hex(6), "sid": sid, "texto": texto, "t": time.time(), "estado": "pendiente", "intentos": 0,
         "autor": autor_, "desde": time.time(), **({} if autor_ == "user" else {"que": que}), **({"audio": audio} if audio and autor_ == "user" else {})}
    _registra(texto, autor_, None if autor_ == "user" else que, guarda=False)
    with _cerrojo:
        _envios.append(e)
    _guarda_envio(e)
    _despierta.set()
    return e["id"]


def orden_envio(ide, accion):
    e = next((x for x in list(_envios) if x["id"] == ide), None)
    if not e:
        return "ese mensaje ya no está en la cola"
    if accion == "vaciar":
        if e["estado"] != "retenido" or not e.get("borrador"):
            return "ya no hay borrador que vaciar"
        e["vaciar"] = True
    elif accion in ("reintentar", "cancelar"):
        e["orden"] = accion
    else:
        return "acción no válida"
    marca_user(e.get("sid"), {"vaciar": "vació la caja", "reintentar": "reintentó un envío", "cancelar": "canceló un envío"}[accion])
    _despierta.set()
    return "ok"




def envios(sid):
    out = []
    for e in [x for x in list(_envios) if x["sid"] == sid][-20:]:
        d = {k: e.get(k) for k in ("id", "texto", "t", "estado", "motivo", "intentos", "desde")}
        d["de"] = "Tú" if _de_user(e) else f"{EDIF} · {e.get('que') or _plantilla(e.get('texto', '')) or 'aviso'}"
        if e["estado"] == "retenido" and e.get("borrador"):
            d["borrador"] = e["borrador"][:300]
        d["atascado"] = _atascado(e)
        out.append(d)
    return out












































