def _escribe_atomico(ruta, texto):
    import tempfile
    os.makedirs(os.path.dirname(ruta), exist_ok=True)
    fd, tmp = tempfile.mkstemp(prefix=os.path.basename(ruta) + ".", suffix=".tmp", dir=os.path.dirname(ruta))
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(texto)
        os.replace(tmp, ruta)
    except BaseException:
        try:
            os.unlink(tmp)
        except OSError:
            pass
        raise


def _url_valida(u):
    u = (u or "").strip()
    return u if re.fullmatch(r"https?://[^\s<>\"']{3,2000}", u, re.I) else None




























class Manejador(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def _responde(self, cuerpo, tipo="application/json"):
        self.send_response(200)
        self.send_header("Content-Type", tipo)
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(cuerpo)

    def _eventos(self):
        q = queue.Queue(maxsize=200)
        with _cerrojo_sse:
            lleno = len(_oyentes) >= MAX_OYENTES
            if not lleno:
                _oyentes.append(q)
        if lleno:
            self.send_error(503)
            return
        try:
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream")
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Accel-Buffering", "no")
            self.end_headers()
            self.wfile.write(b"retry: 2000\nevent: hola\ndata: {}\n\n")
            self.wfile.flush()
            while True:
                try:
                    vistos = [q.get(timeout=15)]
                except queue.Empty:
                    self.wfile.write(b": latido\n\n")
                    self.wfile.flush()
                    continue
                while True:
                    try:
                        vistos.append(q.get_nowait())
                    except queue.Empty:
                        break
                trozos = [f"event: {t}\ndata: {json.dumps({'sid': sid})}\n\n" for t, sid in dict.fromkeys(vistos)]
                self.wfile.write("".join(trozos).encode())
                self.wfile.flush()
        except (BrokenPipeError, ConnectionResetError, OSError):
            pass
        finally:
            with _cerrojo_sse:
                if q in _oyentes:
                    _oyentes.remove(q)

    def do_GET(self):
        if self.path.startswith("/eventos"):
            self._eventos()
        elif self.path.split("?")[0] == "/ajedrez":
            self._responde(json.dumps(ajedrez_srv.lee(CACHE)).encode())
        elif self.path.startswith("/ajedrez/"):
            a = ajedrez_srv.estatico(unquote(urlsplit(self.path).path[9:]), AQUI)
            self._responde(*a) if a else self.send_error(404)
        elif self.path.startswith("/estado.json"):
            self._responde(estado_cuerpo())
        elif self.path.startswith("/pasarela_op?nombre="):
            with _cerrojo_pas:
                op = dict(_pas_op.get(unquote(self.path.split("=", 1)[1])) or {"estado": "ninguna"})
            self._responde(json.dumps(op, ensure_ascii=False).encode())
        elif self.path == "/remote":
            self._responde(visible(json.dumps(remote_edificio(), ensure_ascii=False)).encode())
        elif self.path.startswith("/charla_remote?agente="):
            self._responde(visible(json.dumps(charla_remote(unquote(self.path.split("=", 1)[1])), ensure_ascii=False)).encode())
        elif self.path.startswith("/charla?sid="):
            sid = unquote(self.path.split("=", 1)[1])
            if sid in VIRTUALES:
                self._responde(visible(json.dumps(charla_virtual(sid), ensure_ascii=False)).encode())
                return
            self._responde(visible(json.dumps({"charla": charla(sid), "envios": envios(sid), "chinchetas": chinchetas(sid), "aviso": _gemelas(sid), "ultima": ultima_user((_sesion(sid) or {}).get("name"))}, ensure_ascii=False)).encode())
        elif self.path.split("?")[0] == "/podcast":
            self._responde(json.dumps(podcast(), ensure_ascii=False).encode())
        elif self.path.split("?")[0] == "/podcast/audio":
            q = parse_qs(urlsplit(self.path).query)
            c, f = (q.get("c") or [""])[0], (q.get("f") or [""])[0]
            podcast()
            if f not in _podcast["ficheros"].get(c, ()) or not _RE_M4A.fullmatch(f):
                self.send_error(404)
                return
            self._sirve_rango(os.path.join(PODCAST_VOZ, f), "audio/mp4")
        elif self.path.startswith("/captura/"):
            nombre = os.path.basename(unquote(self.path[len("/captura/"):]))
            ruta = os.path.join(CAPTURAS, nombre)
            if not re.fullmatch(r"[\w.-]+\.(png|jpg|jpeg|gif|webp)", nombre) or not os.path.isfile(ruta):
                self.send_error(404)
                return
            self._responde(open(ruta, "rb").read(), "image/" + nombre.rsplit(".", 1)[1].replace("jpg", "jpeg"))
        elif self.path.startswith("/vivo.json"):

            fuera = ("cartera", "nlv", "nlv_previo", "usd", "finales")
            v = {k: {x: y for x, y in c.items() if x not in fuera} for k, c in vivo().items()}
