def _ent_min():
    e = {k: v for k, v in os.environ.items() if k in ("HOME", "USER", "LOGNAME", "LANG", "TMPDIR", "PATH", "LC_ALL")}
    e.setdefault("PATH", "/usr/local/bin:/usr/bin:/bin")
    return e


def _orden(tipo, d, espera=25):
    """One of the local building's own orders: python3 <package>/edificio.py orden <type> <json>. Returns (ok, text)."""
    py = os.path.join(LOGI_PKG, "edificio.py")
    if not os.path.isfile(py):
        return False, "the building package was not found"
    try:
        r = subprocess.run([sys.executable, py, "orden", tipo, json.dumps(d)], cwd=LOGI_PKG, capture_output=True, text=True, timeout=espera,
                           stdin=subprocess.DEVNULL, env=_ent_min())
    except (OSError, subprocess.SubprocessError) as x:
        return False, type(x).__name__
    return r.returncode == 0, (r.stdout + r.stderr).strip()[:300]


def _estado_sala(nombre):
    return _lee_json(os.path.join(LOGI_ESTADO, nombre + ".json"), {}) or {}


def _buzon(nombre, linea):
    with open(os.path.join(LOGI_ESTADO, nombre + ".buzon.jsonl"), "a", encoding="utf-8") as f:
        f.write(json.dumps(linea, ensure_ascii=False) + "\n")


def _nombre_de(s):
    n = (s or {}).get("name") or ""
    return n if _SALA_OK.match(n) else None


def _entrega(e, s, cola_vista):
    """Delivers a queued message to the room: ONE line in its mailbox (the building's own contract, `de: usuario`). The mirror writes it into the
    transcript once the room's anchor has typed it, which is what _comprueba waits for (so the colours go red, then green, as in the original)."""
    n = _nombre_de(s) or next((v for k, v in plano()["directivos"].items() if plano()["sids"].get(k) == e["sid"] and _SALA_OK.match(v)), None)
    if not n:
        _cierra(e, "no llegó", "esa sala ya no existe en el edificio")
        return
    st = _estado_sala(n)
    if not s and not (st.get("estado_detalle") == "retenida_swap" or st.get("retenida")):
        _cierra(e, "no llegó", "esa sala no tiene sesión abierta (ábrela con la nube o el menú de la sala y vuelve a escribir)")
        return
    if st.get("estado_detalle") == "retenida_swap" or st.get("retenida"):
        _motivo(e, "retenido", "la sala está retenida a propósito por la guarda de swap del edificio (swap %s MB); se entregará sola al bajar" % ((st.get("retenida") or {}).get("swap_mb", "?")))
        return
    ruta = _ruta(e["sid"])
    e["pos"] = os.path.getsize(ruta) if ruta and os.path.isfile(ruta) else 0
    try:
        _buzon(n, {"id": e["id"], "de": "usuario", "texto": e["texto"], "t": time.time()})
    except OSError as x:
        _cierra(e, "no llegó", "no se pudo escribir en su buzón: %s" % x)
        return
    e["via"] = "buzon"
    e["intentos"] += 1
    e["estado"], e["tecleado"], e["desde"] = "tecleado", time.time(), time.time()
    e.pop("motivo", None)
    _guarda_envio(e)


def _gemelas(sid):
    """Warning shown above the chat when what you write may not arrive."""
    if _sesion(sid):
        return None
    n = next((v for k, v in plano()["directivos"].items() if plano()["sids"].get(k) == sid and _SALA_OK.match(v)), None)
    st = _estado_sala(n) if n else {}
    if st.get("estado_detalle") == "retenida_swap" or st.get("retenida"):
        return "esta sala está retenida a propósito por la guarda de swap del edificio: lo que escribas esperará en su buzón hasta que baje el swap"
    return "esta sala no tiene sesión abierta: ábrela (la nube o el menú ⏻ de la sala) y vuelve a escribir"


def bloqueo(s):
    """A permission the room is asking for, taken from the building's state file (the anchor reads it from the room's screen)."""
    n = _nombre_de(s)
    if not n or s.get("status") != "waiting":
        return None
    p = _estado_sala(n).get("permiso")
    if not isinstance(p, dict) or not p.get("firma"):
        return None
    ops = [[i + 1, str(o)[:200], "", False] for i, o in enumerate(p.get("opciones") or [])]
