# ---- local access: Host check, secret cookie, single-use sign-in link (the secret itself never goes in a URL) ----
_COOKIE = "lb"


def _secreto():
    try:
        return open(os.path.join(LOGI_SEG, "web_token"), encoding="utf-8").read().strip()
    except OSError:
        return ""


_GALLETA = hmac.new(_secreto().encode(), b"logi-building-cookie-v1", hashlib.sha256).hexdigest() if _secreto() else ""


def _consume_enlace(n):
    ruta = os.path.join(LOGI_SEG, "web_nonce.json")
    lista = _lee_json(ruta, [])
    lista = lista if isinstance(lista, list) else []
    ahora, ok, resto = time.time(), False, []
    for x in lista:
        if not isinstance(x, dict) or x.get("exp", 0) < ahora:
            continue
        if hmac.compare_digest(str(x.get("n", "")), n):
            ok = True
        else:
            resto.append(x)
    if ok or len(resto) != len(lista):
        fd = os.open(ruta + ".tmp", os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        with os.fdopen(fd, "w") as f:
            json.dump(resto, f)
        os.replace(ruta + ".tmp", ruta)
    return ok


def _cookie_ok(h):
    if not _GALLETA:
        return False
    for parte in (h.headers.get("Cookie") or "").split(";"):
        k, _, v = parte.strip().partition("=")
        if k == _COOKIE and hmac.compare_digest(v, _GALLETA):
            return True
    return False


def _puerta(h, metodo):
    """True if the request may go on. Otherwise the answer has been sent."""
    if (h.headers.get("Host") or "") not in ("127.0.0.1:%d" % PUERTO, "localhost:%d" % PUERTO):
        h.send_error(421, "bad host")
        return False
    u = urlsplit(h.path)
    if metodo == "GET" and u.path == "/ping":
        h._responde(b'{"ok":true}')
        return False
    if metodo == "GET" and u.path == "/" and "n" in parse_qs(u.query):
        if _consume_enlace(parse_qs(u.query)["n"][0]):
            h.send_response(302)
            h.send_header("Location", "/")
            h.send_header("Set-Cookie", "%s=%s; HttpOnly; SameSite=Strict; Path=/; Max-Age=604800" % (_COOKIE, _GALLETA))
            h.send_header("Content-Length", "0")
            h.end_headers()
            return False
    if not _cookie_ok(h):
        cuerpo = ("<!doctype html><meta charset=utf-8><title>Access needed</title><body style='font:16px system-ui;max-width:34em;margin:3em auto;padding:0 1em'>"
                  "<h1>Access needed</h1><p>This is the local logi building screen. Run <code>logi building open</code> in a terminal on this computer "
                  "to get a single-use sign-in link.</p></body>").encode()
        h.send_response(401)
        h.send_header("Content-Type", "text/html; charset=utf-8")
        h.send_header("Content-Length", str(len(cuerpo)))
        h.end_headers()
        if metodo != "HEAD":
            h.wfile.write(cuerpo)
        return False
    return True


_GET0, _POST0, _FIN0 = Manejador.do_GET, Manejador.do_POST, Manejador.end_headers


def _get(self):
    if _puerta(self, "GET"):
        _GET0(self)


def _post(self):
    if _puerta(self, "POST"):
        _POST0(self)


def _fin(self):
    self.send_header("X-Content-Type-Options", "nosniff")
    self.send_header("Referrer-Policy", "no-referrer")
    self.send_header("X-Frame-Options", "SAMEORIGIN")
    _FIN0(self)


Manejador.do_GET, Manejador.do_POST, Manejador.end_headers = _get, _post, _fin


if __name__ == "__main__":
    if not (LOGI_ESTADO and LOGI_SEG and _GALLETA):
        sys.exit("started by `logi building start` only (missing environment or access secret)")
    recupera_envios()
    carga_autoria()
    threading.Thread(target=_mide_sol, daemon=True).start()
    threading.Thread(target=_cartero, daemon=True).start()
    threading.Thread(target=_vigia_cambios, daemon=True).start()
    threading.Thread(target=_hilo_primeros, daemon=True).start()
    srv = ThreadingHTTPServer(("127.0.0.1", PUERTO), Manejador)
    srv.daemon_threads = True
    _pidf = os.environ.get("LOGI_WEB_PIDFILE")
    if _pidf:
        with open(_pidf, "w") as f:
            json.dump({"pid": os.getpid(), "port": PUERTO}, f)
    try:
        srv.serve_forever()
    finally:
        if _pidf:
            try:
                os.remove(_pidf)
            except OSError:
                pass
